import pandas as pd
import numpy as np

# Load data
transport_df = pd.read_csv('chunks_csv/moran_local_2021_transport.csv')
adjacency_df = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Define high/low threshold (median)
threshold = transport_df['Transport_value'].median()

# Classify boroughs
transport_df['category'] = np.where(
    transport_df['Transport_value'] >= threshold, 'high', 'low'
)

# Create neighbor lists
neighbors = adjacency_df.groupby('borough')['neighbor'].apply(list).to_dict()

# Function to check if all neighbors match category
def check_neighbors(borough, category):
    if borough not in neighbors:
        return False  # no neighbors
    neighbor_categories = transport_df.set_index('borough').loc[neighbors[borough], 'category']
    return all(neighbor_categories == category)

# Identify HH/LL boroughs
results = []
for _, row in transport_df.iterrows():
    borough = row['borough']
    category = row['category']
    if check_neighbors(borough, category):
        value = row['Transport_value']
        label = 'HH' if category == 'high' else 'LL'
        results.append((borough, label, value))

# Statistical validation via permutation test (500 shuffles)
if results:
    observed_counts = {'HH': 0, 'LL': 0}
    for _, label, _ in results:
        observed_counts[label] += 1

    # Permutation test
    n_permutations = 500
    permuted_counts = {'HH': [], 'LL': []}
    transport_values = transport_df['Transport_value'].values

    for _ in range(n_permutations):
        shuffled_values = np.random.permutation(transport_values)
        transport_df['shuffled_category'] = np.where(
            shuffled_values >= threshold, 'high', 'low'
        )

        # Count HH/LL in shuffled data
        temp_counts = {'HH': 0, 'LL': 0}
        for _, row in transport_df.iterrows():
            borough = row['borough']
            category = row['shuffled_category']
            if check_neighbors(borough, category):
                temp_counts['HH' if category == 'high' else 'LL'] += 1

        permuted_counts['HH'].append(temp_counts['HH'])
        permuted_counts['LL'].append(temp_counts['LL'])

    # Calculate p-values
    p_values = {}
    for label in ['HH', 'LL']:
        extreme_count = sum(np.array(permuted_counts[label]) >= observed_counts[label])
        p_values[label] = (extreme_count + 1) / (n_permutations + 1)  # +1 for observed

    # Filter results by significance (p < 0.05)
    significant_results = []
    for borough, label, value in results:
        if p_values[label] < 0.05:
            significant_results.append((borough, label, value, p_values[label]))

    results = significant_results

# Prepare output
data_points_used = len(transport_df)
print(f"data_points_used = {data_points_used}")

if results:
    output = []
    for borough, label, value, p_value in results:
        output.append(f"{borough} ({label}, permutation p-value={p_value:.4f})")
    print("FINAL ANSWER: " + ", ".join(output))
else:
    print("FINAL ANSWER: none")
